#include "EnvironmentSystem.h"
#include "../RHI/RHI.h"
bool EnvironmentSystem::Initialize(){Shutdown();auto*d=Velcryn::RHI::GetDevice();if(!d)return false;Velcryn::RHI::TextureDesc t{};t.width=64;t.height=64;t.arrayLayers=6;t.format=Velcryn::RHI::TextureFormat::RGBA16_Float;t.usage=Velcryn::RHI::TextureUsage::Sampled|Velcryn::RHI::TextureUsage::TransferDestination;t.debugName="EnvironmentCube";m_EnvironmentMap=d->CreateTexture(t);t.width=t.height=16;t.debugName="IrradianceCube";m_IrradianceMap=d->CreateTexture(t);return m_EnvironmentMap&&m_IrradianceMap;}void EnvironmentSystem::Shutdown(){if(auto*d=Velcryn::RHI::GetDevice()){if(m_EnvironmentMap)d->DestroyTexture(m_EnvironmentMap);if(m_IrradianceMap)d->DestroyTexture(m_IrradianceMap);}m_EnvironmentMap={};m_IrradianceMap={};}
